import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.CZo9GF0W.js";const u=JSON.parse('{"title":"01 — Functional Spec","description":"","frontmatter":{},"headers":[],"relativePath":"01-SPEC-FUNCTIONAL.md","filePath":"01-SPEC-FUNCTIONAL.md","lastUpdated":1789060268000}'),s={name:"01-SPEC-FUNCTIONAL.md"};function i(r,e,l,d,c,g){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_01-—-functional-spec" tabindex="-1">01 — Functional Spec <a class="header-anchor" href="#_01-—-functional-spec" aria-label="Permalink to &quot;01 — Functional Spec&quot;">​</a></h1><p>Legend: <strong>[P1]</strong> = required for v1.0 · <strong>[P2]</strong> = post-v1 · <strong>[PG]</strong> = Postgres-specific, gated behind a capability flag · <strong>[MM]</strong> = multi-model, Phases 11–13 (<code>10-ENGINE-MODEL.md</code>, <code>11-ENGINE-MONGODB.md</code>, <code>12-ENGINE-REDIS.md</code>).</p><hr><h2 id="a-connections" tabindex="-1">A. Connections <a class="header-anchor" href="#a-connections" aria-label="Permalink to &quot;A. Connections&quot;">​</a></h2><h3 id="a1-creating-a-connection-p1" tabindex="-1">A1. Creating a connection <strong>[P1]</strong> <a class="header-anchor" href="#a1-creating-a-connection-p1" aria-label="Permalink to &quot;A1. Creating a connection **[P1]**&quot;">​</a></h3><p>Sources, all supported:</p><ul><li>Visual form (webview) — host, port, database, user, password, display name, group/folder, color tag, environment tag.</li><li><strong>Paste a URI</strong> — <code>postgres://user:pass@host:5432/db?sslmode=require</code> auto-fills the form. Password extracted straight into SecretStorage, never shown back in plaintext.</li><li><strong>libpq environment</strong> — <code>PGHOST</code>, <code>PGPORT</code>, <code>PGDATABASE</code>, <code>PGUSER</code>, <code>PGPASSWORD</code>, <code>PGSSLMODE</code>, <code>PGSERVICE</code>. <strong>[PG]</strong></li><li><strong><code>~/.pg_service.conf</code></strong> service names, listed in a picker. <strong>[PG]</strong></li><li><strong><code>~/.pgpass</code></strong> consulted for password when none stored. <strong>[PG]</strong></li><li><strong>Docker/Compose detection [P2]</strong> — scan workspace <code>docker-compose.y*ml</code> for <code>postgres</code> services, offer one-click profiles.</li></ul><h3 id="a2-auth-transport-p1" tabindex="-1">A2. Auth &amp; transport <strong>[P1]</strong> <a class="header-anchor" href="#a2-auth-transport-p1" aria-label="Permalink to &quot;A2. Auth &amp; transport **[P1]**&quot;">​</a></h3><ul><li>Password, plus <code>trust</code>/no-password.</li><li>SSL modes: <code>disable | allow | prefer | require | verify-ca | verify-full</code>, with CA / client cert / client key paths and key passphrase. <code>verify-full</code> is the default suggestion for non-localhost hosts.</li><li><strong>SSH tunnel built in</strong> — host, port, user, password | private key + passphrase | ssh-agent; optional jump host. No <code>ssh -L</code> in a separate terminal.</li><li>Connection timeout, statement timeout, <code>application_name</code> (defaults to <code>pitta/&lt;version&gt;</code>), <code>search_path</code>, session <code>TimeZone</code>, <code>client_encoding</code>.</li><li><strong>[P2]</strong> Cloud IAM: AWS RDS auth token, Azure Entra ID, GCP Cloud SQL connector.</li></ul><h3 id="a3-profiles-sharing-p1" tabindex="-1">A3. Profiles &amp; sharing <strong>[P1]</strong> <a class="header-anchor" href="#a3-profiles-sharing-p1" aria-label="Permalink to &quot;A3. Profiles &amp; sharing **[P1]**&quot;">​</a></h3><ul><li><strong>User profiles</strong> — global, in <code>globalState</code> + SecretStorage.</li><li><strong>Workspace profiles</strong> — <code>.vscode/pitta.connections.json</code>, committable, <strong>secrets referenced not stored</strong>: <code>&quot;password&quot;: { &quot;env&quot;: &quot;PGPASSWORD&quot; }</code> or <code>{ &quot;secret&quot;: true }</code> (prompt + keychain on first use) or <code>{ &quot;pgpass&quot;: true }</code>.</li><li>Groups/folders, drag to reorder, per-connection color, duplicate, export/import (secrets stripped).</li></ul><h3 id="a4-environment-tagging-guardrails-p1" tabindex="-1">A4. Environment tagging &amp; guardrails <strong>[P1]</strong> <a class="header-anchor" href="#a4-environment-tagging-guardrails-p1" aria-label="Permalink to &quot;A4. Environment tagging &amp; guardrails **[P1]**&quot;">​</a></h3><p>Each profile carries <code>environment: &quot;dev&quot; | &quot;staging&quot; | &quot;prod&quot;</code>.</p><ul><li>Tree node, status bar, and every result panel border take that environment&#39;s color. Prod = red. Unmissable.</li><li><code>prod</code> implies: destructive-statement confirmation modal, <code>DELETE</code>/<code>UPDATE</code> without <code>WHERE</code> blocked outright, and optional forced read-only.</li><li><code>readOnly: true</code> on any profile → session opens with <code>SET SESSION CHARACTERISTICS AS TRANSACTION READ ONLY</code>, plus client-side statement rejection so the error is instant and legible.</li></ul><h3 id="a5-lifecycle-p1" tabindex="-1">A5. Lifecycle <strong>[P1]</strong> <a class="header-anchor" href="#a5-lifecycle-p1" aria-label="Permalink to &quot;A5. Lifecycle **[P1]**&quot;">​</a></h3><p>Connect / disconnect / reconnect. Pool size configurable (default min 0, max 5). Idle connections closed after N minutes (default 10) — no more holding a prod slot open all afternoon. Auto-reconnect with exponential backoff on transient failure; explicit error toast with the raw <code>SQLSTATE</code> on permanent failure.</p><hr><h2 id="b-ui-mode-—-explorer-visual-editing" tabindex="-1">B. UI mode — Explorer &amp; visual editing <a class="header-anchor" href="#b-ui-mode-—-explorer-visual-editing" aria-label="Permalink to &quot;B. UI mode — Explorer &amp; visual editing&quot;">​</a></h2><h3 id="b1-object-tree-p1" tabindex="-1">B1. Object tree <strong>[P1]</strong> <a class="header-anchor" href="#b1-object-tree-p1" aria-label="Permalink to &quot;B1. Object tree **[P1]**&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Connection (env-colored)</span></span>
<span class="line"><span>└─ Databases                      [PG] multi-db per server</span></span>
<span class="line"><span>   └─ Schemas                     (system schemas collapsed by default)</span></span>
<span class="line"><span>      ├─ Tables      → columns, indexes, constraints, triggers, policies, partitions</span></span>
<span class="line"><span>      ├─ Views</span></span>
<span class="line"><span>      ├─ Materialized Views       [PG]  (+ Refresh action)</span></span>
<span class="line"><span>      ├─ Foreign Tables           [PG]</span></span>
<span class="line"><span>      ├─ Functions / Procedures   (+ source, args, return type)</span></span>
<span class="line"><span>      ├─ Types                    [PG]  enums, composites, domains, ranges</span></span>
<span class="line"><span>      ├─ Sequences                [PG]</span></span>
<span class="line"><span>      └─ Extensions               [PG]</span></span>
<span class="line"><span>   └─ Roles / Privileges          [PG] [P2]</span></span></code></pre></div><ul><li>Lazy-load per node, virtualized. A schema with 10 000 tables must not hang the tree.</li><li>Filter box with fuzzy match across the whole tree.</li><li>Row-count badge — <strong>estimated</strong> from <code>pg_class.reltuples</code> by default (free), exact <code>COUNT(*)</code> on demand only. <strong>[PG]</strong></li><li>Table size / index size / bloat estimate in the hover tooltip. <strong>[PG]</strong></li><li>Context actions per node: Open Data · Open Structure · Copy DDL · Copy qualified name · Generate <code>SELECT</code>/<code>INSERT</code>/<code>UPDATE</code> · Truncate (guarded) · Drop (guarded) · Refresh.</li></ul><h3 id="b2-table-data-view-p1" tabindex="-1">B2. Table Data view <strong>[P1]</strong> <a class="header-anchor" href="#b2-table-data-view-p1" aria-label="Permalink to &quot;B2. Table Data view **[P1]**&quot;">​</a></h3><p>The centerpiece of UI mode.</p><ul><li>Virtualized grid, server-side paging via keyset pagination on the PK (falls back to <code>LIMIT/OFFSET</code> when no PK).</li><li>Per-column filter row: operator picker (<code>= ≠ &gt; &lt; LIKE ILIKE IN IS NULL BETWEEN</code>), values typed per column type; combined into a real <code>WHERE</code>. The generated SQL is always visible and copyable.</li><li>Multi-column sort (click, shift-click), pushed to <code>ORDER BY</code>.</li><li>Column show/hide/reorder/pin/resize, persisted per table.</li><li><strong>Inline editing</strong>: double-click a cell → type-aware editor (text, number w/ exact decimal, boolean tri-state incl. NULL, date/time picker w/ timezone, enum dropdown from <code>pg_enum</code>, json editor with validation, array chip editor, bytea upload/download, FK cell → picker showing referenced-row labels).</li><li>Insert row / duplicate row / delete row.</li><li><strong>Staged changes model</strong>: edits are pending (dirty cells highlighted) until <em>Apply</em>. Apply opens a diff showing the exact DML, then runs it in <strong>one transaction</strong>. Any error → full rollback, nothing half-applied.</li><li>Row identity requires a PK or unique index; without one, editing is disabled with a clear reason and a &quot;use <code>ctid</code>&quot; opt-in. <strong>[PG]</strong></li><li>Cell detail pane for long text / json / images.</li></ul><h3 id="b3-structure-view-p1" tabindex="-1">B3. Structure view <strong>[P1]</strong> <a class="header-anchor" href="#b3-structure-view-p1" aria-label="Permalink to &quot;B3. Structure view **[P1]**&quot;">​</a></h3><p>Read-only tabs for a table: Columns · Indexes · Constraints · Triggers · Policies <strong>[PG]</strong> · Partitions <strong>[PG]</strong> · Statistics · DDL.</p><ul><li><strong>[P2]</strong> Visual table designer: add/rename/drop columns, change types, manage indexes/constraints — generating reviewable <code>ALTER TABLE</code> DDL, never applied silently.</li></ul><h3 id="b4-erd-p2-—-phase-7" tabindex="-1">B4. ERD <strong>[P2 — Phase 7]</strong> <a class="header-anchor" href="#b4-erd-p2-—-phase-7" aria-label="Permalink to &quot;B4. ERD **[P2 — Phase 7]**&quot;">​</a></h3><p>Per-schema canvas, FK edges, auto-layout (dagre), drag to arrange, layout persisted, filter to selected tables + neighbors, export PNG/SVG. Click a table → jump to Structure.</p><hr><h2 id="c-query-mode" tabindex="-1">C. Query mode <a class="header-anchor" href="#c-query-mode" aria-label="Permalink to &quot;C. Query mode&quot;">​</a></h2><h3 id="c1-editor-integration-p1" tabindex="-1">C1. Editor integration <strong>[P1]</strong> <a class="header-anchor" href="#c1-editor-integration-p1" aria-label="Permalink to &quot;C1. Editor integration **[P1]**&quot;">​</a></h3><ul><li>Any <code>.sql</code> file gets a status-bar connection picker. Binding persists per file.</li><li>File-level directive override: <code>-- @pitta connection: staging-analytics</code>.</li><li><strong>CodeLens above each statement:</strong> <code>▶ Run · Explain · Explain Analyze</code>.</li><li>Keybindings: run statement under cursor, run selection, run all, cancel.</li><li>Split-statement execution honors <code>;</code>, dollar-quoted bodies (<code>$$ … $$</code>, <code>$tag$ … $tag$</code>), <code>E&#39;&#39;</code> strings, nested comments, and psql-style <code>\\</code> meta-commands (a useful subset: <code>\\d</code>, <code>\\dt</code>, <code>\\l</code>, <code>\\timing</code>). <strong>[PG]</strong></li></ul><h3 id="c2-executing-p1" tabindex="-1">C2. Executing <strong>[P1]</strong> <a class="header-anchor" href="#c2-executing-p1" aria-label="Permalink to &quot;C2. Executing **[P1]**&quot;">​</a></h3><ul><li>Multiple statements → one result tab each, tabbed panel, per-tab timing + <code>commandTag</code> (<code>SELECT 42</code>, <code>UPDATE 3</code>).</li><li>Live elapsed timer; <strong>Cancel</strong> issues a genuine Postgres CancelRequest.</li><li>Transaction mode toggle: autocommit (default) | manual (<code>BEGIN</code> held open, explicit Commit/Rollback buttons, open-transaction indicator in the status bar — with an idle-in-transaction warning after N seconds). <strong>[PG]</strong></li><li>Stored routines: edit a definition as a document and save it back, call one with its declared arguments, and watch its <code>RAISE</code>/<code>PRINT</code>/warning output arrive while it runs. Failures inside a body are reported with the engine&#39;s own stack.</li><li>Parameterized queries: the engine&#39;s own placeholders (<code>$1</code>, <code>?</code>, <code>@name</code>) and Pitta&#39;s <code>:name</code> prompt for typed values in a form before the run, sent as bind params (never string-interpolated).</li><li><strong>Messages tab</strong>: <code>NOTICE</code>, <code>WARNING</code>, <code>RAISE</code>, <code>\\timing</code> output — streamed live during execution, not after. <strong>[PG]</strong></li></ul><h3 id="c3-result-grid-p1" tabindex="-1">C3. Result grid <strong>[P1]</strong> <a class="header-anchor" href="#c3-result-grid-p1" aria-label="Permalink to &quot;C3. Result grid **[P1]**&quot;">​</a></h3><p>Same component as B2, read-only unless the result maps to exactly one updatable table.</p><ul><li>Copy as: TSV, CSV, JSON, Markdown table, SQL <code>INSERT</code>.</li><li>Export: CSV, JSON, JSONL, XLSX, SQL inserts, Parquet <strong>[P2]</strong> — streamed to disk, never fully materialized.</li><li>Result-set search, column stats popover (min/max/distinct/null count over the fetched window), chart-this-result <strong>[P2]</strong>.</li><li>Pin/compare two result tabs side by side <strong>[P2]</strong>.</li></ul><h3 id="c4-sql-intelligence-p1-unless-noted" tabindex="-1">C4. SQL intelligence <strong>[P1 unless noted]</strong> <a class="header-anchor" href="#c4-sql-intelligence-p1-unless-noted" aria-label="Permalink to &quot;C4. SQL intelligence **[P1 unless noted]**&quot;">​</a></h3><ul><li>Completion: schemas, tables, columns (alias-aware, <code>FROM</code>-clause-driven), functions with signatures, keywords, enum values in comparisons. Backed by the metadata cache → instant.</li><li>Hover: column type/default/nullability/comment; table row-estimate and size.</li><li>Go-to-definition on a table/function name → opens its DDL.</li><li>Diagnostics: syntax errors from a real parser (<code>libpg-query</code> WASM, the actual Postgres grammar) plus semantic checks — unknown table/column, ambiguous column. <strong>[PG]</strong></li><li>Formatter (<code>prettier-plugin-sql</code> or <code>sql-formatter</code>), format-on-save opt-in.</li><li>Snippets + user-defined templates.</li></ul><h3 id="c5-history-saved-queries-p1" tabindex="-1">C5. History &amp; saved queries <strong>[P1]</strong> <a class="header-anchor" href="#c5-history-saved-queries-p1" aria-label="Permalink to &quot;C5. History &amp; saved queries **[P1]**&quot;">​</a></h3><ul><li>Every execution recorded: SQL, connection, timestamp, duration, row count, success/error. Stored locally, searchable, re-runnable, with a &quot;don&#39;t record on prod&quot; opt-out.</li><li>Saved queries as plain <code>.sql</code> files in a workspace folder — no proprietary store, works with git.</li></ul><h3 id="c6-sql-notebooks-p2-—-phase-5" tabindex="-1">C6. SQL Notebooks <strong>[P2 — Phase 5]</strong> <a class="header-anchor" href="#c6-sql-notebooks-p2-—-phase-5" aria-label="Permalink to &quot;C6. SQL Notebooks **[P2 — Phase 5]**&quot;">​</a></h3><p><code>.psql-nb</code> via the Notebook API: markdown + SQL cells, per-cell connection, outputs as grids, cell chaining via a <code>-- @pitta ref: prevCell</code> reference, export to <code>.sql</code> or <code>.ipynb</code>.</p><hr><h2 id="d-postgres-power-features-pg-—-phase-6" tabindex="-1">D. Postgres power features <strong>[PG — Phase 6]</strong> <a class="header-anchor" href="#d-postgres-power-features-pg-—-phase-6" aria-label="Permalink to &quot;D. Postgres power features **[PG — Phase 6]**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Detail</th></tr></thead><tbody><tr><td><strong>EXPLAIN visualizer</strong></td><td><code>EXPLAIN (ANALYZE, BUFFERS, VERBOSE, FORMAT JSON)</code> → interactive node tree. Per-node cost/rows/time, width proportional to time, red-flag badges for estimate-vs-actual row skew &gt; 10×, seq scans on big tables, external sorts, lossy bitmap heap scans, nested-loop blowups. Plan diff between two runs.</td></tr><tr><td><strong>Session monitor</strong></td><td><code>pg_stat_activity</code> live: state, wait event, query, duration, blocking chain. Cancel backend / terminate backend from the UI (guarded).</td></tr><tr><td><strong>Lock inspector</strong></td><td><code>pg_locks</code> join → who blocks whom, as a tree.</td></tr><tr><td><strong>LISTEN/NOTIFY</strong></td><td>Subscribe to channels, live payload log.</td></tr><tr><td><strong>Index &amp; health advisor</strong></td><td>Unused indexes (<code>pg_stat_user_indexes</code>), duplicate indexes, missing FK indexes, table/index bloat estimate, seq-scan-heavy tables, autovacuum lag. Read-only reporting with suggested DDL — never auto-applies.</td></tr><tr><td><strong>Extensions</strong></td><td>List installed/available, version, <code>CREATE EXTENSION</code> helper.</td></tr><tr><td><strong>pgvector awareness</strong></td><td><code>vector</code> columns render as a compact summary + dimension, similarity-search snippet generation, index (<code>ivfflat</code>/<code>hnsw</code>) visibility.</td></tr><tr><td><strong>PostGIS awareness</strong></td><td>Geometry cells render a mini map preview; <code>ST_AsGeoJSON</code> on demand.</td></tr><tr><td><strong>Roles &amp; privileges</strong></td><td>Role tree, membership, per-object grants matrix.</td></tr><tr><td><strong>Publications / subscriptions / replication slots</strong></td><td>Read-only listing with lag.</td></tr></tbody></table><h2 id="e-schema-tooling-phase-7" tabindex="-1">E. Schema tooling <strong>[Phase 7]</strong> <a class="header-anchor" href="#e-schema-tooling-phase-7" aria-label="Permalink to &quot;E. Schema tooling **[Phase 7]**&quot;">​</a></h2><ul><li>DDL generation for every object type, <code>pg_dump</code>-quality (round-trips).</li><li><strong>Schema diff</strong> between two connections/schemas → generated migration SQL, reviewed before it runs anywhere.</li><li>Export schema to a migration file compatible with plain SQL / Flyway naming.</li><li><strong>[P2]</strong> Read-only awareness of Prisma / Drizzle / Alembic migration state if detected in the workspace.</li></ul><h2 id="f-cross-cutting-p1" tabindex="-1">F. Cross-cutting <strong>[P1]</strong> <a class="header-anchor" href="#f-cross-cutting-p1" aria-label="Permalink to &quot;F. Cross-cutting **[P1]**&quot;">​</a></h2><ul><li>Full theme integration — uses VS Code theme tokens; light/dark/high-contrast all correct. No hardcoded colors.</li><li>Keyboard-navigable everywhere; screen-reader labels on grid cells; grid is a proper ARIA <code>grid</code>.</li><li>All long ops cancellable and reported through <code>withProgress</code>.</li><li>Output channel with leveled logging; secrets redacted; &quot;Copy diagnostics&quot; for bug reports.</li><li>Telemetry: <strong>off by default</strong>, opt-in, honors <code>telemetry.telemetryLevel</code>, documented event list.</li></ul><hr><h2 id="g-non-relational-engines-mm-—-phases-11–13" tabindex="-1">G. Non-relational engines <strong>[MM — Phases 11–13]</strong> <a class="header-anchor" href="#g-non-relational-engines-mm-—-phases-11–13" aria-label="Permalink to &quot;G. Non-relational engines **[MM — Phases 11–13]**&quot;">​</a></h2><p>Everything in A–F holds for MongoDB and Redis unless it is gated on a capability that says otherwise. This section is only what is <em>new</em>, and each item has a decision behind it in <code>09-DECISIONS.md</code>.</p><h3 id="g1-one-client-several-kinds-of-database" tabindex="-1">G1. One client, several kinds of database <a class="header-anchor" href="#g1-one-client-several-kinds-of-database" aria-label="Permalink to &quot;G1. One client, several kinds of database&quot;">​</a></h3><ul><li>A connection declares an engine and a <strong>language</strong> (<code>sql</code>, <code>mongodb</code>, <code>redis</code>). The status bar shows connection · database · language; a query file carries the engine&#39;s extension (<code>.sql</code>, <code>.mongodb.js</code>, <code>.redis</code>); saved queries, history and notebooks are language-generic (ADR-034).</li><li>Every affordance stays capability-gated. Redis has no explain tab, no ERD, no schema diff, and no DDL document — those commands are <code>when</code>-hidden, not present-and-broken.</li><li>Capabilities may be narrowed by the <em>session</em>: transactions on a MongoDB standalone, <code>CLIENT LIST</code> under a restricted Redis ACL user (ADR-035).</li></ul><h3 id="g2-documents-mm" tabindex="-1">G2. Documents <strong>[MM]</strong> <a class="header-anchor" href="#g2-documents-mm" aria-label="Permalink to &quot;G2. Documents **[MM]**&quot;">​</a></h3><ul><li>A result may be a set of documents rather than rows. Columns come from a sample of the page, marked as inferred, <code>_id</code> first; the raw document is always in the detail pane and always the last view offered (ADR-038, ADR-033).</li><li><strong>A missing field is not a null field.</strong> The grid has a <code>MISSING</code> token distinct from <code>NULL</code>, filters offer <code>exists</code> / <code>does not exist</code>, and clearing a field and removing a field are two different edit actions (ADR-039).</li><li>A collection&#39;s field list is <strong>inferred by sampling</strong> and every surface that shows it says so, with observed types and presence as percentages (ADR-045). A <code>$jsonSchema</code> validator, where one exists, is shown separately and is not an inference.</li></ul><h3 id="g3-keyspaces-mm" tabindex="-1">G3. Keyspaces <strong>[MM]</strong> <a class="header-anchor" href="#g3-keyspaces-mm" aria-label="Permalink to &quot;G3. Keyspaces **[MM]**&quot;">​</a></h3><ul><li>A Redis database is a flat keyspace; the folder tree is built from key prefixes over a bounded sample, and folder counts are labelled as estimates. Listing is always <code>SCAN</code>-based and paged; <code>KEYS</code> is never issued (ADR-044).</li><li>A key opens the data view, with columns that depend on its type — hash field/value, zset member/score, stream id/fields, list index/value.</li><li><strong>TTL is first-class</strong>: shown on the key, editable, and guarded like any other write.</li></ul><h3 id="g4-editing-without-a-rollback-mm" tabindex="-1">G4. Editing without a rollback <strong>[MM]</strong> <a class="header-anchor" href="#g4-editing-without-a-rollback-mm" aria-label="Permalink to &quot;G4. Editing without a rollback **[MM]**&quot;">​</a></h3><ul><li>Staged edits, dirty cells and the preview-before-apply flow are unchanged; the preview shows the engine&#39;s own command.</li><li>Where the engine cannot apply a batch atomically the dialog says so in those words, and the result reports exactly which edits were applied (ADR-041).</li></ul><h3 id="g5-safety-per-engine-mm" tabindex="-1">G5. Safety, per engine <strong>[MM]</strong> <a class="header-anchor" href="#g5-safety-per-engine-mm" aria-label="Permalink to &quot;G5. Safety, per engine **[MM]**&quot;">​</a></h3><ul><li>Classification comes from the engine&#39;s own metadata where it publishes any — Redis <code>COMMAND INFO</code> flags, MongoDB&#39;s operation verb plus an empty-filter test — and an <strong>unclassifiable command on a <code>prod</code> profile is treated as destructive</strong> (ADR-040).</li><li><code>deleteMany({})</code> and <code>updateMany({})</code> are the analogue of DML with no <code>WHERE</code> and are blocked by the same setting. An aggregation containing <code>$out</code> or <code>$merge</code> is a write, and is classified by what the pipeline does rather than by the method name.</li><li><code>FLUSHALL</code>, <code>FLUSHDB</code>, <code>CONFIG SET</code>, <code>SHUTDOWN</code>, <code>MIGRATE</code> and the rest of the flag table&#39;s <code>dangerous</code> set need the typed confirmation on prod. <code>KEYS</code> and <code>MONITOR</code> are refused rather than confirmed.</li><li>MongoDB query text is <strong>parsed, never evaluated</strong> — no <code>eval</code>, no <code>vm</code>, no <code>new Function</code>, so a snippet pasted from a ticket cannot reach the extension host (ADR-042).</li><li>Read-only enforcement is client-side where the engine has no server-side read-only session, and the badge says which it is rather than implying a guarantee the server is not making.</li></ul><h3 id="g6-what-these-engines-do-not-get" tabindex="-1">G6. What these engines do not get <a class="header-anchor" href="#g6-what-these-engines-do-not-get" aria-label="Permalink to &quot;G6. What these engines do not get&quot;">​</a></h3><ul><li>No ERD and no schema diff for MongoDB — an inferred relationship is a guess, and a diagram of guesses is worse than none. Index and validator diffing is a separate, honest feature. <strong>[P2]</strong></li><li>No plan visualizer for Redis; there is no planner.</li><li>No cross-engine query, ever (ADR-048).</li><li>No client-side field-level encryption or Kerberos for MongoDB — both need native modules, which ADR-012 rules out (ADR-046).</li></ul>`,66)])])}const h=o(s,[["render",i]]);export{u as __pageData,h as default};
